target.css:
:root {
  --ink: #183445;
  --muted: #64808c;
  --ocean: #087f8c;
  --deep-ocean: #075d70;
  --foam: #e8f7f5;
  --surface: #ffffff;
  --line: #cbe4e4;
  --coral: #ef7968;
  --coral-pale: #fff0ec;
  --sun: #f5bd4b;
}

.dive-card {
  box-sizing: border-box;
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.dive-card * {
  box-sizing: border-box;
}

.dive-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 12px;
}

.title-block {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--ocean);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  line-height: 1;
  text-transform: uppercase;
}

.dive-card h1,
.dive-card h2,
.dive-card p {
  margin: 0;
}

.dive-card h1 {
  font-size: 21px;
  font-weight: 750;
  letter-spacing: -0.4px;
  line-height: 1.1;
}

.sync-badge {
  padding: 5px 8px;
  color: var(--deep-ocean);
  background: var(--foam);
  border: 1px solid var(--line);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 750;
}

.stat-strip {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0 16px;
  overflow: hidden;
  background: var(--foam);
  border: 1px solid var(--line);
  border-radius: 11px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px 11px;
  border-right: 1px solid var(--line);
}

.stat:last-child {
  border-right: 0;
}

.highlight-stat {
  background: var(--coral-pale);
}

.stat-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  text-transform: uppercase;
}

.stat strong {
  font-size: 15px;
  line-height: 1.1;
}

.log-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 128px;
  gap: 10px;
  padding: 12px 16px;
}

.task-panel {
  min-width: 0;
}

.panel-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 5px;
}

.panel-heading h2,
.site-note h2 {
  font-size: 12px;
  font-weight: 800;
  line-height: 1.2;
}

.panel-heading span {
  color: var(--coral);
  font-size: 10px;
  font-weight: 750;
}

.task-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 0;
  margin: 0;
  list-style: none;
}

.task-list li {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: center;
  gap: 6px;
  min-height: 25px;
  padding: 4px 7px 4px 4px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 7px;
  font-size: 11px;
  font-weight: 650;
  line-height: 1.1;
}

.check {
  display: grid;
  width: 17px;
  height: 17px;
  place-items: center;
  color: var(--ocean);
  background: var(--foam);
  border-radius: 5px;
  font-size: 10px;
  font-weight: 850;
}

.done .check {
  color: var(--surface);
  background: var(--ocean);
}

.task-list time {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.site-note {
  position: relative;
  padding: 9px 10px;
  background: var(--deep-ocean);
  border-radius: 10px;
  color: var(--surface);
}

.note-icon {
  position: absolute;
  top: 7px;
  right: 9px;
  color: var(--sun);
  font-size: 22px;
  font-weight: 800;
  line-height: 1;
}

.site-note h2 {
  padding-right: 20px;
  color: var(--foam);
}

.site-note p {
  margin-top: 7px;
  color: var(--surface);
  font-size: 11px;
  font-weight: 550;
  line-height: 1.35;
}

.tag {
  display: inline-block;
  margin-top: 8px;
  padding: 3px 6px;
  color: var(--deep-ocean);
  background: var(--sun);
  border-radius: 4px;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.4px;
  text-transform: uppercase;
}

.dive-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 16px;
  color: var(--muted);
  background: var(--foam);
  border-top: 1px solid var(--line);
  font-size: 10px;
  font-weight: 650;
}

.actions {
  display: flex;
  gap: 6px;
}

.actions button {
  padding: 6px 9px;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
}

.secondary {
  color: var(--deep-ocean);
  background: var(--surface);
  border: 1px solid var(--line);
}

.primary {
  color: var(--surface);
  background: var(--coral);
  border: 1px solid var(--coral);
}

